import{_ as o,C as a,o as l,c as i,j as n,a as u,E as s,a2 as r}from"./chunks/framework.BxGh02fV.js";const b=JSON.parse('{"title":"Profil et préférences","description":"","frontmatter":{"title":"Profil et préférences"},"headers":[],"relativePath":"guide/preferences.md","filePath":"guide/preferences.md"}'),g={name:"guide/preferences.md"};function p(d,e,c,m,f,h){const t=a("Capture");return l(),i("div",null,[e[0]||(e[0]=n("h1",{id:"profil-et-preferences",tabindex:"-1"},[u("Profil et préférences "),n("a",{class:"header-anchor",href:"#profil-et-preferences","aria-label":'Permalink to "Profil et préférences"'},"​")],-1)),e[1]||(e[1]=n("p",null,"Les préférences regroupent tout ce qui vaut pour l'application entière, quel que soit le projet ouvert : votre identité, le thème, la langue, les connexions aux assistants IA, les mises à jour. Ouvrez-les avec ⌘ , (Ctrl+, sous Windows et Linux) ou en cliquant sur votre nom en haut à droite de la fenêtre. Pour en sortir, cliquez sur un onglet ou sur l'icône de grille.",-1)),s(t,{name:"profil",alt:"Préférences, onglet Identité : nom, e-mail et auteur par défaut"}),e[2]||(e[2]=r('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>À gauche, un rail de catégories sous le titre <strong>Préférences</strong> et un badge <strong>S&#39;applique à toute l&#39;application</strong>. À droite, le contenu de la catégorie choisie. Les catégories, de haut en bas : <strong>Identité</strong>, <strong>Apparence</strong>, <strong>Routage LLM</strong>, <strong>MCP &amp; Skills</strong>, <strong>Modèle de stack</strong>, <strong>Normes</strong>, <strong>Mises à jour</strong> et <strong>Prise en main</strong>.</p><h2 id="identite" tabindex="-1">Identité <a class="header-anchor" href="#identite" aria-label="Permalink to &quot;Identité&quot;">​</a></h2><p>C&#39;est une identité locale, sans compte. Elle signe vos décisions, specs et commits.</p><ul><li><strong>Changer la photo</strong> : choisissez une image d&#39;avatar ; <strong>Retirer</strong> la supprime.</li><li><strong>Nom</strong> (obligatoire), <strong>E-mail</strong> (vérifié s&#39;il est rempli) et <strong>Auteur par défaut</strong> (obligatoire) : la signature de votre travail.</li><li><strong>Enregistrer</strong> valide le tout ; l&#39;écran confirme « Modifications enregistrées ».</li></ul><h2 id="apparence" tabindex="-1">Apparence <a class="header-anchor" href="#apparence" aria-label="Permalink to &quot;Apparence&quot;">​</a></h2>',6)),s(t,{name:"preferences",alt:"Préférences, onglet Apparence : thème et langue"}),e[3]||(e[3]=r('<ul><li><strong>Thème</strong> : <strong>Clair</strong>, <strong>Sombre</strong> ou <strong>Système</strong> (suit le thème de votre ordinateur).</li><li><strong>Confort de lecture</strong> : <strong>Compact</strong>, <strong>Standard</strong> ou <strong>Confortable</strong> — la taille des éléments et la densité de l&#39;interface, ensemble.</li><li><strong>Langue</strong> : une liste déroulante — <strong>Français</strong>, <strong>English</strong>, <strong>Español</strong> ou <strong>Русский</strong>.</li></ul><p>Le changement s&#39;applique tout de suite. Le thème et le confort se règlent aussi depuis la barre du haut, sans ouvrir les préférences : le bouton soleil/lune bascule entre clair et sombre, et le menu <strong>Aa</strong> choisit le confort de lecture.</p><h3 id="palettes-des-tuiles" tabindex="-1">Palettes des tuiles <a class="header-anchor" href="#palettes-des-tuiles" aria-label="Permalink to &quot;Palettes des tuiles&quot;">​</a></h3><p>La carte <strong>Palettes des tuiles</strong> liste les quatre palettes fournies et les vôtres. <strong>Dupliquer</strong> copie une palette en palette personnelle ; vous en choisissez les cinq couleurs et le nom (Entrée valide), <strong>Supprimer</strong> la retire, <strong>Nouvelle palette</strong> en crée une. Vos palettes valent dans tous vos projets.</p>',4)),s(t,{name:"preferences-palettes",alt:"La carte Palettes des tuiles : quatre palettes fournies et une palette personnelle"}),e[4]||(e[4]=r('<h2 id="routage-llm" tabindex="-1">Routage LLM <a class="header-anchor" href="#routage-llm" aria-label="Permalink to &quot;Routage LLM&quot;">​</a></h2><p>Le profil de routage global : une <strong>Matrice</strong> qui associe un modèle et un effort à chaque niveau, plus un modèle de repli. <strong>Enregistrer</strong> garde le profil ; <strong>Enregistrer comme preset</strong> en fait un preset nommé. La liste <strong>Presets</strong> montre les presets de base et les vôtres ; <strong>Appliquer</strong> en charge un (il reste à enregistrer). Sans profil, l&#39;écran propose d&#39;appliquer un preset de base puis d&#39;enregistrer.</p><p>C&#39;est une suggestion : Effortless n&#39;appelle aucun agent, l&#39;agent consulte ce profil.</p><h2 id="mcp-skills" tabindex="-1">MCP &amp; Skills <a class="header-anchor" href="#mcp-skills" aria-label="Permalink to &quot;MCP &amp; Skills&quot;">​</a></h2><p>Installe le serveur Effortless et ses skills dans vos assistants IA, en un geste.</p><ul><li>Une carte d&#39;état dit si le <strong>Binaire</strong> d&#39;Effortless est <strong>résolu</strong> ou <strong>introuvable</strong>, et combien de clients ont Effortless enregistré.</li><li>La liste des assistants, sous <strong>Applications</strong>, indique pour chacun s&#39;il est <strong>Détecté</strong> sur votre poste et son état : <strong>Prêt</strong>, <strong>Partiel</strong> ou <strong>Rien de configuré</strong>.</li><li>Sélectionnez les assistants (<strong>Sélectionner les détectés</strong> coche ceux qui sont détectés), puis <strong>Déployer</strong> ou <strong>Désinstaller</strong>. Un récapitulatif compte ce qui a été créé, mis à jour, laissé inchangé ou en erreur. <strong>Rafraîchir le statut</strong> relit l&#39;état.</li><li>La section <strong>Serveur</strong> porte la <strong>Commande</strong> (le chemin de l&#39;exécutable ; « Exécutable introuvable. » si l&#39;application n&#39;a pas pu se localiser) et la case <strong>Accorder les permissions (zéro-prompt)</strong>. Sous <strong>Avancé</strong> : les <strong>Arguments</strong>, l&#39;<strong>Environnement</strong> et les <strong>Outils exposés</strong>.</li></ul><h2 id="modele-de-stack" tabindex="-1">Modèle de stack <a class="header-anchor" href="#modele-de-stack" aria-label="Permalink to &quot;Modèle de stack&quot;">​</a></h2><p>Choisissez un modèle dans <strong>Modèles disponibles</strong> (le badge <strong>Projet</strong> signale un modèle propre au projet). Son détail montre son build et son cycle. Renseignez l&#39;<strong>Identifiant de la stack</strong>, la <strong>Source de norme</strong> (<strong>Embarquée (par défaut)</strong> ou <strong>Dépôt partagé (git)</strong>) et les <strong>Variables</strong> requises, puis <strong>Créer la stack</strong>.</p><h2 id="normes" tabindex="-1">Normes <a class="header-anchor" href="#normes" aria-label="Permalink to &quot;Normes&quot;">​</a></h2><p>L&#39;<strong>Adresse du dépôt</strong> de normes de développement partagé par tous vos projets (dossier local ou URL git ; vide pour la retirer) et, en option, la <strong>Branche ou tag (git)</strong>. <strong>Enregistrer</strong> garde la source. <strong>Mettre à jour tous les projets</strong> les synchronise et donne le résultat (« 2 projet(s) mis à jour, 0 en échec », par exemple).</p><p>La synchronisation se fait aussi toute seule au démarrage de l&#39;application et à l&#39;ouverture d&#39;un projet ; une notification l&#39;annonce quand des normes ont changé. La norme locale d&#39;un projet n&#39;est jamais modifiée.</p><h2 id="mises-a-jour" tabindex="-1">Mises à jour <a class="header-anchor" href="#mises-a-jour" aria-label="Permalink to &quot;Mises à jour&quot;">​</a></h2>',12)),s(t,{name:"preferences-mises-a-jour",alt:"Préférences, catégorie Mises à jour : canal, version courante, vérification et options"}),e[5]||(e[5]=r('<ul><li>Choisissez un <strong>Canal</strong>. Un canal <strong>Privé</strong> peut demander une authentification <code>gh</code> ; l&#39;écran dit pourquoi il n&#39;est pas disponible.</li><li>La <strong>Version courante</strong> est affichée. <strong>Vérifier les mises à jour</strong> dit « Tu es à jour » ou « Mise à jour disponible : » avec la version, ses <strong>Nouveautés</strong>, et le bouton <strong>Mettre à jour vers …</strong>.</li><li>Avant d&#39;installer, Effortless doit arrêter les sessions MCP en cours : une fenêtre « Sessions à arrêter avant la mise à jour » les liste, et <strong>Tout arrêter et mettre à jour</strong> lance l&#39;installation. La progression s&#39;affiche (téléchargement, vérification de la signature, installation, redémarrage).</li></ul><p>Deux options :</p><ul><li><strong>Vérifier les mises à jour au lancement</strong> : à chaque démarrage, Effortless vérifie le canal et, si une version est disponible, l&#39;annonce par une notification. Rien ne s&#39;installe sans votre geste : l&#39;installation se fait ici. Le panneau vérifie aussi à son ouverture.</li><li><strong>Ne plus demander avant d&#39;arrêter les sessions</strong> : la fenêtre de confirmation ne s&#39;affiche plus.</li></ul><p>Si une ancienne installation est détectée, un bandeau « Installation legacy détectée » propose <strong>Migrer vers le compilé</strong>.</p><h2 id="prise-en-main" tabindex="-1">Prise en main <a class="header-anchor" href="#prise-en-main" aria-label="Permalink to &quot;Prise en main&quot;">​</a></h2><p><strong>Relancer l&#39;introduction</strong> rejoue le premier lancement (identité, déploiement, workspace) : voir <a href="/Effortless/guide/first-run.html">Premier lancement</a>.</p><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p>Le déploiement MCP &amp; Skills sert précisément à relier l&#39;application à vos agents. Côté agent, <code>effortless_deploy</code> fait le même travail, et <code>effortless_ndd_source</code> lit ou règle la source de normes.</p><p>Pour Claude Code, le déploiement installe aussi la <strong>barre d&#39;état</strong> Effortless (<code>~/.claude/effortless/statusline.mjs</code>) : dossier, modèle, branche, part du contexte utilisée — lue dans la vraie taille de la fenêtre du modèle —, quotas 5 h et 7 jours, puis, dans un projet Effortless, la phase, le mode et la story active. Si vous avez déjà votre propre barre d&#39;état, elle est conservée : le compte rendu du déploiement donne la ligne à poser pour adopter celle d&#39;Effortless.</p>',9))])}const _=o(g,[["render",p]]);export{b as __pageData,_ as default};
